S.append(S2(c,B+' · 1','Vì sao dùng hàm?',card('Chương trình con',P('<b>Hàm</b> là đoạn lệnh có tên, làm một việc cụ thể, <b>gọi lại nhiều lần</b>.','Lợi ích: <b>tránh lặp mã</b>; <b>chia nhỏ</b> bài toán lớn; <b>dễ kiểm thử, dễ sửa</b>; nhiều người cùng làm.','Hàm có sẵn: <code>len, max, print</code>… Hàm do ta viết: dùng <code>def</code>.')),CODE('def chao(ten):\n    print("Xin chao", ten)\n\nchao("An")\nchao("Binh")',24)+R('def chao(ten):\n    print("Xin chao", ten)\n\nchao("An")\nchao("Binh")','',24,'Kết quả')+KEY('<b>def</b> chỉ <b>định nghĩa</b> hàm, chưa chạy. Hàm chỉ chạy khi <b>được gọi</b>.')))
S.append(S2(c,B+' · 1','Cú pháp hàm và lời gọi',card('Các thành phần',ul(['<code>def tên(tham_số):</code> — dòng đầu, có dấu <b>:</b>.','Thân hàm <b>thụt lề</b>.','<code>return giá_trị</code> — trả kết quả và <b>kết thúc hàm</b>.','Gọi: <code>tên(đối_số)</code>.','<b>Tham số</b>: tên trong định nghĩa; <b>đối số</b>: giá trị truyền khi gọi.'],7)),CODE('def binh_phuong(x):\n    return x * x\n\nprint(binh_phuong(5))\nprint(binh_phuong(3) + binh_phuong(4))\nkq = binh_phuong(2) ** 2\nprint(kq)',22)+R('def binh_phuong(x):\n    return x * x\n\nprint(binh_phuong(5))\nprint(binh_phuong(3) + binh_phuong(4))\nkq = binh_phuong(2) ** 2\nprint(kq)','',24,'Kết quả')))
S.append(TB(c,B+' · 1','print và return khác nhau',['','print','return'],[['Tác dụng','<b>hiện</b> giá trị lên màn hình','<b>trả</b> giá trị về nơi gọi, <b>kết thúc hàm</b>'],['Dùng tiếp kết quả?','không (hàm trả None)','<b>có</b> (gán, tính tiếp)'],['Lệnh sau nó trong hàm','vẫn chạy','<b>không chạy</b>'],['Ví dụ','<code>def f(x): print(x * 2)</code>','<code>def f(x): return x * 2</code>']],note=KEY('Hàm không có <b>return</b> (hoặc <code>return</code> trống) trả về <b>None</b>. Lỗi hay gặp: <code>y = f(3) + 1</code> khi f chỉ print → TypeError.')))
S.append(S2(c,B+' · 1','Hàm không return trả về None',card('Chứng minh bằng chương trình',P('<code>kq = f(3)</code> với f chỉ có print: kq nhận <b>None</b>.','<code>None + 1</code> gây <b>TypeError</b>.')),CODE('def f(x):\n    print(x * 2)\n\ndef g(x):\n    return x * 2\n\na = f(3)\nb = g(3)\nprint(a, b)\nprint(b + 1)\nprint(a + 1)',22)+R('def f(x):\n    print(x * 2)\n\ndef g(x):\n    return x * 2\n\na = f(3)\nb = g(3)\nprint(a, b)\nprint(b + 1)','',22,'Kết quả (đến dòng 10)')+RES(OUT(ERR('def f(x):\n    print(x * 2)\na = f(3)\nprint(a + 1)'),20),'Dòng cuối gây lỗi')))
S.append(S2(c,B+' · 1','Trả về nhiều giá trị; return sớm',card('Tuple và thoát sớm',P('<code>return a, b</code> thực chất trả về <b>một tuple</b>; nhận bằng <code>x, y = f()</code>.','<b>return</b> kết thúc hàm ngay, nên dùng để <b>thoát sớm</b> khi đã biết kết quả.')),CODE('def min_max(a):\n    return min(a), max(a)\n\nlo, hi = min_max([4, 9, 2])\nprint(lo, hi, min_max([4, 9, 2]))\n\ndef co_chan(a):\n    for x in a:\n        if x % 2 == 0:\n            return True\n    return False\nprint(co_chan([1, 3, 4, 5]), co_chan([1, 3]))',20)+R('def min_max(a):\n    return min(a), max(a)\n\nlo, hi = min_max([4, 9, 2])\nprint(lo, hi, min_max([4, 9, 2]))\n\ndef co_chan(a):\n    for x in a:\n        if x % 2 == 0:\n            return True\n    return False\nprint(co_chan([1, 3, 4, 5]), co_chan([1, 3]))','',22,'Kết quả')+KEY('<b>return False</b> phải nằm <b>ngoài vòng for</b> (sau khi duyệt hết). Đặt trong vòng lặp là lỗi phổ biến.')))
S.append(S2(c,B+' · 2','Tham số: vị trí, tên, mặc định',card('Ba cách truyền',P('<b>Theo vị trí</b>: <code>f(2, 3)</code>.','<b>Theo tên</b>: <code>f(b=3, a=2)</code> — thứ tự tuỳ ý.','<b>Giá trị mặc định</b>: <code>def f(a, b=10)</code>; tham số có mặc định phải <b>đứng sau</b> tham số không mặc định.','<code>*args</code> nhận <b>số lượng tuỳ ý</b> đối số (thành tuple).')),CODE('def luy_thua(a, n=2):\n    return a ** n\n\nprint(luy_thua(5))\nprint(luy_thua(2, 10))\nprint(luy_thua(n=3, a=2))\n\ndef tong(*args):\n    return sum(args)\nprint(tong(1, 2, 3, 4))',21)+R('def luy_thua(a, n=2):\n    return a ** n\n\nprint(luy_thua(5))\nprint(luy_thua(2, 10))\nprint(luy_thua(n=3, a=2))\n\ndef tong(*args):\n    return sum(args)\nprint(tong(1, 2, 3, 4))','',22,'Kết quả')))
S.append(S2(c,B+' · 2','Truyền vào hàm: biến bên ngoài có bị đổi không?',card('Số và xâu (bất biến)',P('Truyền <b>số, xâu, tuple</b> (bất biến): đổi trong hàm <b>không ảnh hưởng</b> biến bên ngoài.','Truyền <b>list, dict, set</b> (khả biến) và sửa tại chỗ: <b>biến bên ngoài bị đổi</b>.')),CODE('x = 10\ndef f(x):\n    x += 5\n    return x\ny = f(x)\nprint(x, y)\n\ndef them(a):\n    a.append(0)\nds = [1]\nthem(ds)\nprint(ds)',21)+R('x = 10\ndef f(x):\n    x += 5\n    return x\ny = f(x)\nprint(x, y)\n\ndef them(a):\n    a.append(0)\nds = [1]\nthem(ds)\nprint(ds)','',24,'Kết quả')+KEY('x ngoài hàm vẫn là <b>10</b>; x trong hàm là biến cục bộ cùng tên. Danh sách thì bị đổi.')))
S.append(S2(c,B+' · 2','Bẫy: tham số mặc định là danh sách',card('Mặc định chỉ tạo MỘT LẦN',P('Giá trị mặc định được <b>tạo một lần</b> khi định nghĩa hàm; nếu là list thì <b>mọi lần gọi dùng chung</b> list đó.','Cách đúng: mặc định <b>None</b>, tạo list mới trong hàm.')),CODE('def them(x, ds=[]):\n    ds.append(x)\n    return ds\n\na = them(1)\nb = them(2)\nc = them(3, [])\nprint(a, b, c, a is b)\n\ndef dung(x, ds=None):\n    if ds is None:\n        ds = []\n    ds.append(x)\n    return ds\nprint(dung(1), dung(2))',20)+R('def them(x, ds=[]):\n    ds.append(x)\n    return ds\n\na = them(1)\nb = them(2)\nc = them(3, [])\nprint(a, b, c, a is b)\n\ndef dung(x, ds=None):\n    if ds is None:\n        ds = []\n    ds.append(x)\n    return ds\nprint(dung(1), dung(2))','',22,'Kết quả')+KEY('a và b là <b>cùng một danh sách</b> [1, 2]; c dùng danh sách riêng [3].')))
S.append(S2(c,B+' · 2','Hàm gọi hàm, hàm trả về hàm',card('Tổ hợp hàm',P('Hàm có thể <b>gọi hàm khác</b>: chia nhỏ bài toán.','Hàm cũng là <b>giá trị</b>: truyền làm đối số, hoặc trả về.')),CODE('def nt(n):\n    return n > 1 and all(n % d for d in range(2, int(n ** 0.5) + 1))\n\ndef dem_nt(a, b):\n    return sum(1 for i in range(a, b + 1) if nt(i))\n\nprint(dem_nt(1, 50))\n\ndef ap_dung(f, ds):\n    return [f(x) for x in ds]\nprint(ap_dung(abs, [-3, 4, -5]))',20)+R('def nt(n):\n    return n > 1 and all(n % d for d in range(2, int(n ** 0.5) + 1))\n\ndef dem_nt(a, b):\n    return sum(1 for i in range(a, b + 1) if nt(i))\n\nprint(dem_nt(1, 50))\n\ndef ap_dung(f, ds):\n    return [f(x) for x in ds]\nprint(ap_dung(abs, [-3, 4, -5]))','',22,'Kết quả')))
S.append(S2(c,B+' · 2','Hàm lambda',card('Hàm ẩn danh một dòng',P('<code>lambda tham_số: biểu_thức</code> — trả về giá trị biểu thức.','Hay dùng làm <b>key</b> khi sắp xếp, hoặc với <code>map</code>, <code>filter</code>.','Chỉ chứa <b>một biểu thức</b>, không có lệnh.')),CODE('b = lambda x: x * x\nprint(b(7))\nt = ["lan", "an", "binh"]\nprint(sorted(t, key=lambda w: len(w)))\nprint(list(map(lambda x: x + 1, [1, 2, 3])))\nprint(list(filter(lambda x: x % 2, range(8))))',21)+R('b = lambda x: x * x\nprint(b(7))\nt = ["lan", "an", "binh"]\nprint(sorted(t, key=lambda w: len(w)))\nprint(list(map(lambda x: x + 1, [1, 2, 3])))\nprint(list(filter(lambda x: x % 2, range(8))))','',22,'Kết quả')))
# phạm vi
S.append(S2(c,B+' · 3','Biến cục bộ và biến toàn cục',card('Quy tắc LEGB đơn giản',P('<b>Cục bộ</b>: biến tạo ra <b>trong hàm</b>, chỉ tồn tại khi hàm chạy.','<b>Toàn cục</b>: biến tạo ở <b>ngoài mọi hàm</b>, hàm <b>đọc</b> được.','Trong hàm, <b>gán</b> cho một tên là tạo biến <b>cục bộ mới</b> (che biến toàn cục cùng tên).')),CODE('x = 7\ndef g():\n    x = 3\n    return x * 2\n\ndef doc():\n    return x + 1\n\ny = g()\nprint(x, y, doc())\nprint(z)\ndef k():\n    z = 5\nk()\nprint(z)',22)+R('x = 7\ndef g():\n    x = 3\n    return x * 2\n\ndef doc():\n    return x + 1\n\ny = g()\nprint(x, y, doc())','',24,'Kết quả')+RES(OUT(ERR('def k():\n    z = 5\nk()\nprint(z)'),20),'z cục bộ không dùng được bên ngoài')))
S.append(S2(c,B+' · 3','Lỗi UnboundLocalError',card('Vừa đọc vừa gán trong hàm',P('Nếu trong hàm có <b>phép gán</b> cho một tên thì tên đó là <b>cục bộ trong cả hàm</b>, kể cả ở những dòng trước phép gán.','Đọc nó trước khi gán → <b>UnboundLocalError</b>.','Muốn sửa biến toàn cục: khai báo <b>global</b>.')),CODE('dem = 0\ndef tang():\n    dem += 1\n\ntang()',24)+RES(OUT(ERR('dem = 0\ndef tang():\n    dem += 1\ntang()'),20),'Kết quả')+CODE('dem = 0\ndef tang():\n    global dem\n    dem += 1\n\ntang()\ntang()\nprint(dem)',22)+R('dem = 0\ndef tang():\n    global dem\n    dem += 1\ntang()\ntang()\nprint(dem)','',24,'Sau khi thêm global')))
S.append(S2(c,B+' · 3','global và nonlocal',card('Khai báo phạm vi',P('<b>global x</b>: trong hàm, <b>x là biến toàn cục</b> (cho phép gán).','<b>nonlocal x</b>: trong hàm lồng, <b>x là biến của hàm bao ngoài</b> (không phải toàn cục).','Chỉ cần khai báo khi <b>gán</b>; chỉ đọc thì không cần.')),CODE('x = 10\ndef f():\n    x = 20\n    def g():\n        nonlocal x\n        x += 1\n        return x\n    return g()\ndef h():\n    global x\n    x += 5\n    return x\nprint(f(), x, h(), x)',20)+R('x = 10\ndef f():\n    x = 20\n    def g():\n        nonlocal x\n        x += 1\n        return x\n    return g()\ndef h():\n    global x\n    x += 5\n    return x\nprint(f(), x, h(), x)','',24,'Kết quả')+KEY('Thứ tự tính: f() = 21 (x toàn cục vẫn 10); h() đổi x thành 15 nên <b>4 giá trị: 21, 10, 15, 15</b>.')))
S.append(TB(c,B+' · 3','Theo dõi phạm vi biến của chương trình trên',['Lệnh','x toàn cục','x của f','Ghi chú'],[['<code>x = 10</code>','10','—','tạo biến toàn cục'],['<code>f()</code> gán x = 20','10','20','x cục bộ của f, che x toàn cục'],['<code>g()</code>: nonlocal x += 1','10','<b>21</b>','g đổi x của f; trả 21'],['<code>h()</code>: global x += 5','<b>15</b>','—','đổi biến toàn cục'],['<code>print(…, x)</code> sau cùng','15','—','in 21, 10, 15, 15']],note=KEY('Python tính các đối số của print <b>từ trái sang phải</b>: giá trị x thứ hai được lấy <b>trước khi h() chạy</b>, nên là 10.')))
S.append(S2(c,B+' · 3','Nên tránh biến toàn cục',card('Nguyên tắc lập trình tốt',P('Hàm tốt chỉ phụ thuộc vào <b>tham số</b> và cho kết quả qua <b>return</b> (hàm “thuần”).','Dùng biến toàn cục làm hàm khó kiểm thử, dễ lỗi khi nhiều hàm cùng sửa.','Ngoại lệ hợp lí: <b>hằng số</b> (viết hoa: <code>MAX = 100</code>).')),CODE('# xấu\ntong = 0\ndef cong(a):\n    global tong\n    tong += a\n\n# tốt\ndef cong2(tong, a):\n    return tong + a\n\nt = 0\nfor v in [3, 4, 5]:\n    t = cong2(t, v)\nprint(t)',22)+R('def cong2(tong, a):\n    return tong + a\n\nt = 0\nfor v in [3, 4, 5]:\n    t = cong2(t, v)\nprint(t)','',24,'Kết quả')))
S.append(S2(c,B+' · 4','Thiết kế chương trình bằng hàm',card('Chia để trị',STEPS(['Xác định <b>đầu vào, đầu ra</b> của bài.','Tách thành các <b>việc nhỏ</b>, mỗi việc một hàm.','Đặt tên hàm <b>rõ nghĩa</b> (động từ), viết <b>chú thích</b> ngắn.','<b>Kiểm thử từng hàm</b> trước khi ghép lại.'])),CODE('def doc_day():\n    return list(map(int, input().split()))\n\ndef tb(a):\n    return sum(a) / len(a)\n\ndef dem_tren_tb(a):\n    m = tb(a)\n    return sum(1 for x in a if x > m)\n\na = doc_day()\nprint(f"{tb(a):.2f}", dem_tren_tb(a))',21)+R('def doc_day():\n    return list(map(int, input().split()))\n\ndef tb(a):\n    return sum(a) / len(a)\n\ndef dem_tren_tb(a):\n    m = tb(a)\n    return sum(1 for x in a if x > m)\n\na = doc_day()\nprint(f"{tb(a):.2f}", dem_tren_tb(a))','4 8 15 16 23 42\n',22,'Kết quả')))
S.append(S2(c,B+' · 4','Docstring và kiểu gợi ý',card('Tài liệu hoá hàm',P('<b>Docstring</b>: xâu ba nháy ngay dưới dòng def, mô tả hàm; xem bằng <code>help(f)</code>.','<b>Gợi ý kiểu</b> (type hint): <code>def f(a: int) -&gt; int:</code> — chỉ để đọc hiểu, Python <b>không bắt buộc</b>.','Đặt tên tham số rõ nghĩa tốt hơn chú thích dài.')),CODE('def uoc_chung(a: int, b: int) -> int:\n    """Tra ve UCLN cua a va b (Euclid)."""\n    while b:\n        a, b = b, a % b\n    return a\n\nprint(uoc_chung(48, 18))\nprint(uoc_chung.__doc__)',21)+R('def uoc_chung(a: int, b: int) -> int:\n    """Tra ve UCLN cua a va b (Euclid)."""\n    while b:\n        a, b = b, a % b\n    return a\n\nprint(uoc_chung(48, 18))\nprint(uoc_chung.__doc__)','',22,'Kết quả')))
S.append(SELF(c,B+' · 5','Tự kiểm tra: phạm vi và giá trị','Chương trình in ra gì?','x = 7\ndef g():\n    x = 3\n    return x * 2\ndef h():\n    global x\n    x = x + 1\ny = g()\nh()\nprint(x, y)',P('<code>g()</code>: x cục bộ = 3 → trả <b>6</b>, không đổi x toàn cục; y = 6.','<code>h()</code>: dùng <b>global</b>, x toàn cục = 7 + 1 = <b>8</b>.','In: <b>8 6</b>.')+R('x = 7\ndef g():\n    x = 3\n    return x * 2\ndef h():\n    global x\n    x = x + 1\ny = g()\nh()\nprint(x, y)','',24,'Kết quả thật'),21))
S.append(SELF(c,B+' · 5','Tự kiểm tra (HSG): hàm sinh bình phương','Chương trình in ra gì? (Chú ý f(0).)','def f(n):\n    kq = []\n    for i in range(n):\n        kq.append(i * i)\n    return kq\nprint(f(4), len(f(0)))',P('f(4): i = 0, 1, 2, 3 → [0, 1, 4, 9].','f(0): range(0) rỗng → trả về <b>[]</b> (không phải None) → len = 0.')+R('def f(n):\n    kq = []\n    for i in range(n):\n        kq.append(i * i)\n    return kq\nprint(f(4), len(f(0)))','',24,'Kết quả thật'),21))
S.append(SELF(c,B+' · 5','Tự kiểm tra (HSG): return đặt sai chỗ','Hàm sau định kiểm tra “mọi phần tử đều dương”. Cho kết quả với [3, -1, 5] và [4, 6]. Sửa lỗi.','def all_pos(a):\n    for x in a:\n        if x > 0:\n            return True\n    return False',P('Hàm trả True <b>ngay khi gặp một số dương</b>. Với [3, −1, 5]: gặp 3 → True (sai, vì có −1). Với [4, 6]: True (đúng).','Tư duy đúng: “tất cả dương” nghĩa là <b>không có phần tử nào không dương</b>.','<b>Sửa</b>: <code>for x in a: if x &lt;= 0: return False</code> rồi <code>return True</code> ở <b>ngoài vòng lặp</b>; hoặc <code>return all(x &gt; 0 for x in a)</code>.')+R('def all_pos(a):\n    for x in a:\n        if x > 0:\n            return True\n    return False\ndef dung(a):\n    return all(x > 0 for x in a)\nprint(all_pos([3, -1, 5]), all_pos([4, 6]), dung([3, -1, 5]))','',22,'Kết quả thật'),20))
S+=END(c,B,['<b>def tên(tham_số):</b>; <b>return</b> trả giá trị và kết thúc hàm; thiếu return → <b>None</b>.','<b>print</b> chỉ hiện, <b>return</b> mới trả về.','Tham số: vị trí, theo tên, <b>mặc định</b> (đặt sau cùng), <b>*args</b>.','<b>Biến cục bộ</b> che biến toàn cục; sửa toàn cục cần <b>global</b>, hàm lồng cần <b>nonlocal</b>.','Tham số <b>list</b> bị sửa tại chỗ thì list bên ngoài đổi; số, xâu thì không.','<b>Mặc định list rỗng</b> là bẫy: dùng <b>None</b>.'],[('Trả về','return'),('Sửa biến toàn cục','global x'),('Hàm ẩn danh','lambda x: …'),('Không có return','None')],'Dùng print thay return; quên global; đặt return False trong vòng lặp; mặc định là list.',['Đối số được tính từ <b>trái sang phải</b>.','<code>return a, b</code> trả tuple.','Chỉ cần <b>global/nonlocal</b> khi <b>gán</b>.','Đừng đặt tên biến trùng hàm có sẵn (<code>sum</code>, <code>max</code>…).'],['<b>Decorator</b>, <b>closure</b>.','<b>Hàm đệ quy</b> (bài 7).','<b>Generator</b> với yield.'],
 [('Hàm không return trả về?',),('<code>def f(a, b=2): return a*b</code>; <code>f(3)</code>?',),('Khai báo nào cho phép gán biến toàn cục trong hàm?',),('<code>(lambda x: x+1)(4)</code>?',),('<code>def f(*a): return len(a)</code>; <code>f(1,2,3)</code>?',)],
 [('<b>None</b>.',),('<b>6</b>.',),('<b>global</b>.',),('<b>5</b>.',),('<b>3</b>.',)],
 [('Mức 1. Viết hàm <code>max3(a, b, c)</code> trả số lớn nhất, không dùng max.',),('Mức 1. Viết hàm <code>dao(n)</code> đảo ngược số nguyên dương. Thử 1230.',),('Mức 2. Viết hàm <code>la_nt(n)</code> và dùng nó đếm số nguyên tố trong khoảng [a, b]. Thử [10, 50].',),('Mức 2. Hàm <code>chuan(s)</code> chuẩn hoá tên: bỏ khoảng trắng thừa, viết hoa chữ đầu mỗi từ.',),('Mức 3 (HSG). Viết hàm <code>dem_cap(a, k)</code> đếm số cặp (i &lt; j) có a[i] + a[j] = k trong O(n) bằng dict. Thử [3,1,4,1,5,9,2,6], k = 7.',),('Mức 3 (HSG). Viết hàm nhận danh sách số và trả về <b>hai giá trị</b>: phần tử xuất hiện nhiều nhất (nhỏ nhất nếu hoà) và số lần xuất hiện. Thử [3,1,3,2,1,3,1].',)],
 [('<code>def max3(a,b,c): m=a; … </code> (giống slide “Số lớn nhất của ba số”).',),(V('def dao(n):\n    d=0\n    while n:\n        d=d*10+n%10\n        n//=10\n    return d\nprint(dao(1230))')+'.',),(V('def nt(n):\n    return n>1 and all(n%d for d in range(2,int(n**.5)+1))\nprint(sum(nt(i) for i in range(10,51)))')+' số.',),('<code>" ".join(w.capitalize() for w in s.split())</code>.',),(V('def dem_cap(a,k):\n    d={};t=0\n    for x in a:\n        t+=d.get(k-x,0);d[x]=d.get(x,0)+1\n    return t\nprint(dem_cap([3,1,4,1,5,9,2,6],7))')+' cặp.',),(V('def f(a):\n    d={}\n    for x in a: d[x]=d.get(x,0)+1\n    m=max(d.values())\n    return min(k for k in d if d[k]==m), m\nprint(f([3,1,3,2,1,3,1]))')+' (tuple).',)],hper=2)
mkdeck('p4a.html','Python 4A · Hàm và phạm vi biến',S)
